<?php require 'config.php';$pageTitle='Restaurants';$rows=$pdo->query("SELECT * FROM restaurants WHERE approved=1 ORDER BY name")->fetchAll();include 'partials/header.php';?>
<h1>Restaurants near you</h1><p class="muted">Choose a restaurant to explore its menu.</p><div class="grid"><?php foreach($rows as $r):?><article class="card"><div class="food-emoji">🍽️</div><h3><?=e($r['name'])?></h3><p class="muted"><?=e($r['area'])?> · <?=e($r['address'])?></p><a class="btn" href="menu.php?id=<?=$r['id']?>">See food menu</a></article><?php endforeach;?><?php if(!$rows):?><p>No approved restaurants yet.</p><?php endif;?></div><?php include 'partials/footer.php';?>
